import java.sql.*;
import javax.servlet.http.*;
import javax.servlet.*;
import java.io.*;
import java.util.logging.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String columns = req.getParameter("columns");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("csv|json|xml")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Build column selection - user can specify which columns to export
        String columnClause = "*";
        if (columns != null && !columns.isEmpty()) {
            // Allow alphanumeric and commas for column lists
            columnClause = columns;
        }

        String query = "SELECT " + columnClause + " FROM financial_reports WHERE report_id = '" + reportId + "'";
        log.info("Executing export query for report: " + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/" + (format != null ? format : "json"));
            resp.setHeader("Content-Disposition", "attachment; filename=report_" + reportId + "." + (format != null ? format : "json"));

            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            if ("csv".equals(format)) {
                for (int i = 1; i <= colCount; i++) {
                    out.print(meta.getColumnName(i));
                    if (i < colCount) out.print(",");
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        out.print(rs.getString(i));
                        if (i < colCount) out.print(",");
                    }
                    out.println();
                }
            } else {
                out.println("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.println(",");
                    out.print("{");
                    for (int i = 1; i <= colCount; i++) {
                        out.print("\"" + meta.getColumnName(i) + "\":");
                        out.print("\"" + rs.getString(i) + "\"");
                        if (i < colCount) out.print(",");
                    }
                    out.print("}");
                    first = false;
                }
                out.println("]");
            }
        } catch (SQLException e) {
            log.severe("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch export - accepts JSON body with multiple report IDs
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }
        String ids = body.toString().replaceAll("[\\[\\]\"\\s]", "");
        String query = "SELECT * FROM financial_reports WHERE report_id IN ('" + ids.replace(",", "','") + "')";
        log.info("Batch export query: " + query);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.println("{\"count\": " + 0 + ", \"status\": \"exported\"}");
        } catch (SQLException e) {
            resp.sendError(500, "Error: " + e.getMessage());
        }
    }
}
